import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"', strict=False)

    parsed_rows = []
    try:
        for row in reader:
            parsed_rows.append([value for value in row])
    except csv.Error:
        pass

    header_index = None
    for index, row in enumerate(parsed_rows):
        normalized = [re.sub(r"\s+", " ", value.strip()).casefold() for value in row]
        if "organisation name" in normalized and "supplier name" in normalized:
            header_index = index
            break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = parsed_rows[header_index][:]
    data_rows = []
    for row in parsed_rows[header_index + 1:]:
        if not any(value.strip() for value in row):
            continue
        data_rows.append(row[:])

    width = max([23, len(columns)] + [len(row) for row in data_rows])
    columns.extend([""] * (width - len(columns)))
    normalized_rows = []
    for row in data_rows:
        normalized_rows.append(row + [""] * (width - len(row)))

    return {"columns": columns, "rows": normalized_rows}
